507	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
508	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
509	     * re-derived elsewhere.
510	     */
511	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
512	        "1", 10,
513	        "61", 9);
514	
515	    /**
516	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
517	     * E.164 digit string, choosing the longest matching code known to
518	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
519	     * country code. This is the single place a country code is read from an E.164 number, so every
520	     * rule keyed by that code shares one derivation.
521	     */
522	    private static String countryCodeOf(String e164Digits) {
523	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
524	            .filter(e164Digits::startsWith)
525	            .max(Comparator.comparingInt(String::length))
526	            .orElse(null);
527	    }
528	
529	    /**
530	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
531	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
532	     * known code wins; a number whose country code is not recognised passes this check (its length is
533	     * then governed only by the general E.164 bound), while a recognised code must be followed by
534	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
535	     */
536	    public static boolean hasValidNationalLength(String e164Digits) {
537	        String countryCode = countryCodeOf(e164Digits);
538	        if (countryCode == null) {
539	            return true;
540	        }
541	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
542	    }
543	
544	    /**
545	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
546	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
547	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
548	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
549	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
550	     */
551	    public Integer getMembershipPoints() {
552	        int points = 0;
553	        if (hasEmail()) {
554	            points += 2;
555	        }
556	        if (hasNoNamesakes()) {
557	            points += 1;
558	        }
559	        if (hasLargeHousehold()) {
560	            points += 2;
561	        }
562	        if (hasQualifyingTenure()) {
563	            points += 3;
564	        }
565	        return points;
566	    }
567	
568	    /**
569	     * The owner's membership level, a number from 1 to 4. For an owner created through the
570	     * creation pipeline this is the value assigned and stored at creation time; an owner that
571	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
572	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
573	     * membershipPoints. This is the single value read by the API for an owner's membership level.
574	     */
575	    public Integer getMembershipLevel() {
576	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
577	    }
578	
579	    public void setMembershipLevel(Integer membershipLevel) {
580	        this.membershipLevel = membershipLevel;
581	    }
582	
583	    /**
584	     * The owner's base membership level, a number from 1 to 4 derived directly from
585	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
586	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
587	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
588	     */
589	    public Integer getBaseMembershipLevel() {
590	        int points = getMembershipPoints();
591	        if (points >= 6) {
592	            return 4;
593	        }
594	        if (points >= 4) {
595	            return 3;
596	        }
597	        if (points >= 2) {
598	            return 2;
599	        }
600	        return 1;
601	    }
602	
603	    /**
604	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
605	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
606	     * known, is treated as not a large household.
607	     */
608	    private boolean hasLargeHousehold() {
609	        return this.householdSize != null && this.householdSize >= 3;
610	    }
611	
612	    /**
613	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
614	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
615	     * email presence so the check is never re-derived elsewhere.
616	     */
617	    private boolean hasEmail() {
618	        return this.email != null && !this.email.isEmpty();
619	    }
620	
621	    /**
622	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
623	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
624	     * not known, is treated as not unique.
625	     */
626	    private boolean hasNoNamesakes() {
627	        return this.namesakeCount != null && this.namesakeCount == 0;
628	    }
629	
630	    /**
631	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
632	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
633	     * is crossed only once at least one fiscal-year boundary has passed since registration.
634	     */
635	    private boolean hasQualifyingTenure() {
636	        return this.getTenureFiscalYears() >= 1;
637	    }
638	
639	    /**
640	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
641	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
642	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
643	     * created owner has zero tenure). Never negative.
644	     */
645	    public long getTenureFiscalYears() {
646	        if (this.registrationDate == null) {
647	            return 0;
648	        }
649	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
650	    }
651	
652	    /**
653	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
654	     * otherwise {@code 'PHONE'}.
655	     */
656	    public String getContactPreference() {
657	        return hasEmail() ? "EMAIL" : "PHONE";
658	    }
659	
660	    /**
661	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
662	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
663	     * the national digits grouped into threes from the left separated by spaces,
664	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
665	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
666	     * E.164 form, or carries no known country code.
667	     */
668	    public String getTelephoneDisplay() {
669	        if (this.telephone == null || !this.telephone.startsWith("+")) {
670	            return this.telephone;
671	        }
672	        String digits = this.telephone.substring(1);
673	        String countryCode = countryCodeOf(digits);
674	        if (countryCode == null) {
675	            return this.telephone;
676	        }
677	        String national = digits.substring(countryCode.length());
678	        StringBuilder groups = new StringBuilder();
679	        for (int i = 0; i < national.length(); i += 3) {
680	            if (groups.length() > 0) {
681	                groups.append(' ');
682	            }
683	            groups.append(national, i, Math.min(i + 3, national.length()));
684	        }
685	        return "+" + countryCode + " " + groups;
686	    }
687	
688	    /**
689	     * The owner's identity key: the single derived value used for duplicate detection. It is the
690	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
691	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
692	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
693	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
694	     * rejected with {@code 409}, only when their whole identity keys are equal.
695	     */
696	    public String getIdentityKey() {
697	        String telephonePart = this.telephone == null ? "" : this.telephone;
698	        String emailPart = this.email == null ? "" : this.email;
699	        String soundexPart = soundex(this.getLastName());
700	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
701	    }
702	
703	    /**
704	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
705	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
706	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
707	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
708	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
709	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
710	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
711	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
712	     */
713	    public static String soundex(String name) {
714	        if (name == null) {
715	            return "";
716	        }
717	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
718	        if (letters.isEmpty()) {
719	            return "";
720	        }
721	        StringBuilder code = new StringBuilder();
722	        code.append(letters.charAt(0));
723	        char previous = soundexDigit(letters.charAt(0));
724	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
725	            char c = letters.charAt(i);
726	            char digit = soundexDigit(c);
727	            if (digit != '0' && digit != previous) {
728	                code.append(digit);
729	            }
730	            if (c != 'H' && c != 'W') {
731	                previous = digit;
732	            }
733	        }
734	        while (code.length() < 4) {
735	            code.append('0');
736	        }
737	        return code.toString();
738	    }
739	
740	    /**
741	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
742	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
743	     */
744	    private static char soundexDigit(char c) {
745	        switch (c) {
746	            case 'B': case 'F': case 'P': case 'V':
747	                return '1';
748	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
749	                return '2';
750	            case 'D': case 'T':
751	                return '3';
752	            case 'L':
753	                return '4';
754	            case 'M': case 'N':
755	                return '5';
756	            case 'R':
757	                return '6';
758	            default:
759	                return '0';
760	        }
761	    }
762	
763	    protected Set<Pet> getPetsInternal() {
764	        if (this.pets == null) {
765	            this.pets = new HashSet<>();
766	        }
767	        return this.pets;
768	    }
769	
770	    protected void setPetsInternal(Set<Pet> pets) {
771	        this.pets = pets;
772	    }
773	
774	    public List<Pet> getPets() {
775	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
776	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
777	        return Collections.unmodifiableList(sortedPets);
778	    }
779	
780	    public void setPets(List<Pet> pets) {
781	        this.pets = new HashSet<>(pets);
782	    }
783	
784	    public void addPet(Pet pet) {
785	        getPetsInternal().add(pet);
786	        pet.setOwner(this);
787	    }
788	
789	    /**
790	     * Return the Pet with the given name, or null if none found for this Owner.
791	     *
792	     * @param name to test
793	     * @return true if pet name is already in use
794	     */
795	    public Pet getPet(String name) {
796	        return getPet(name, false);
797	    }
798	
799	    /**
800	     * Return the Pet with the given name, or null if none found for this Owner.
801	     *
802	     * @param name to test
803	     * @return true if pet name is already in use
804	     */
805	    public Pet getPet(String name, boolean ignoreNew) {
806	        name = name.toLowerCase();
807	        for (Pet pet : getPetsInternal()) {
808	            if (!ignoreNew || !pet.isNew()) {
809	                String compName = pet.getName();
810	                compName = compName.toLowerCase();
811	                if (compName.equals(name)) {
812	                    return pet;
813	                }
814	            }
815	        }
816	        return null;
817	    }
818	
819	    public Pet getPet(Integer petId) {
820	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
821	    }
822	
823	    @Override
824	    public String toString() {
825	        return new ToStringCreator(this)
826	
827	            .append("id", this.getId())
828	            .append("new", this.isNew())
829	            .append("lastName", this.getLastName())
830	            .append("firstName", this.getFirstName())
831	            .append("address", this.address)
832	            .append("city", this.city)
833	            .append("telephone", this.telephone)
834	            .append("email", this.email)
835	            .toString();
836	    }
837	}
